// Characterization tests: pin the HTTP behaviour clients see today, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 2.5, C: 60, D: 0.3 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})
const json = async (res) => ({ status: res.status, type: res.headers.get('content-type'), body: await res.json() })

test('POST /orders creates an order and returns 201 JSON', async () => {
  const { status, type, body } = await json(await post({ items: [{ sku: 'A', qty: 2 }] }))
  assert.equal(status, 201)
  assert.equal(type, 'application/json')
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(body.items, [{ sku: 'A', qty: 2 }])
  assert.equal(body.total, 20)
})

test('ids are strings, sequential', async () => {
  const a = (await json(await post({ items: [{ sku: 'A', qty: 1 }] }))).body.id
  const b = (await json(await post({ items: [{ sku: 'A', qty: 1 }] }))).body.id
  assert.equal(Number(b), Number(a) + 1)
})

test('total sums multiple items', async () => {
  const { body } = await json(await post({ items: [{ sku: 'A', qty: 1 }, { sku: 'C', qty: 1 }] }))
  assert.equal(body.total, 70)
})

test('total is floored to a whole number', async () => {
  const { body } = await json(await post({ items: [{ sku: 'B', qty: 3 }] })) // 7.5
  assert.equal(body.total, 7)
  const small = await json(await post({ items: [{ sku: 'D', qty: 1 }] })) // 0.3
  assert.equal(small.body.total, 0)
})

test('no discount at exactly 100', async () => {
  const { body } = await json(await post({ items: [{ sku: 'A', qty: 10 }] }))
  assert.equal(body.total, 100)
})

test('10% discount applies above 100, then floors', async () => {
  const over = await json(await post({ items: [{ sku: 'A', qty: 11 }] })) // 110 -> 99
  assert.equal(over.body.total, 99)
  const frac = await json(await post({ items: [{ sku: 'C', qty: 2 }, { sku: 'B', qty: 1 }] })) // 122.5 -> 110.25
  assert.equal(frac.body.total, 110)
})

test('invalid requests return 400 { error: "items required" }', async () => {
  const cases = [
    post({}), post({ items: [] }), post({ items: 'x' }), post(null, '{not json'), post(null, ''),
  ]
  for (const p of cases) {
    const { status, body } = await json(await p)
    assert.equal(status, 400)
    assert.deepEqual(body, { error: 'items required' })
  }
})

test('GET /orders/:id returns the stored order', async () => {
  const created = (await json(await post({ items: [{ sku: 'C', qty: 1 }] }))).body
  const { status, type, body } = await json(await fetch(`${base}/orders/${created.id}`))
  assert.equal(status, 200)
  assert.equal(type, 'application/json')
  assert.deepEqual(body, created)
})

test('GET unknown order returns 200 with { error: "not found" } (current quirk)', async () => {
  const { status, body } = await json(await fetch(`${base}/orders/does-not-exist`))
  assert.equal(status, 200)
  assert.deepEqual(body, { error: 'not found' })
})

test('unknown routes and methods return 404 { error: "no route" }', async () => {
  for (const [method, path] of [['GET', '/'], ['GET', '/orders'], ['PUT', '/orders'], ['DELETE', '/orders/1'], ['POST', '/orders/1'], ['GET', '/orders/1/x']]) {
    const { status, body } = await json(await fetch(base + path, { method }))
    assert.equal(status, 404, `${method} ${path}`)
    assert.deepEqual(body, { error: 'no route' })
  }
})

test('query string is ignored when routing', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 1 }] })
  const { body } = await json(await fetch(`${base}/orders/${(await res.json()).id}?x=1`))
  assert.equal(body.total, 10)
})
